INSERT INTO `document_version` (
    document_id, version_number, content_id, content_hash, extracted_content_id,
    parse_status, parser_version, parsed_at, change_summary, created_by_user_id, created_at
) VALUES (
    #{documentId}, #{versionNumber}, #{contentId}, #{contentHash}, #{extractedContentId},
    #{parseStatus}, #{parserVersion}, #{parsedAt}, #{changeSummary}, #{createdByUserId}, #{createdAt}
)

mapper.select:
SELECT id, document_id, version_number, content_id, content_hash, extracted_content_id,
       parse_status, parser_version, parsed_at, change_summary, created_by_user_id, created_at
FROM `document_version`
WHERE document_id = #{documentId}
  AND version_number = #{versionNumber}
LIMIT 1
